  rateLabel.appendChild(rateInput);
  wrap.appendChild(rateLabel);

  // 保存语音设置
  const vBtnRow = document.createElement('div');
  vBtnRow.className = 'chat-settings-actions';
  const vSave = document.createElement('button');
