// ===== Voice I/O via Web Speech API (pure client-side, no backend) =====
// - STT: window.SpeechRecognition / webkitSpeechRecognition
// - TTS: window.speechSynthesis
// Graceful degradation: if a capability is missing, the UI hides the control
// and the helper functions become no-ops.
const SR = (typeof window !== 'undefined') && (window.SpeechRecognition || window.webkitSpeechRecognition);
const synth = (typeof window !== 'undefined') && window.speechSynthesis;

export function sttSupported() { return !!SR; }
export function ttsSupported() { return !!synth; }

// App locale ('zh' | 'en' | ...) -> BCP-47 tag for speech engines.
function langTag(lang) {
  if (lang === 'en') return 'en-US';
  if (lang === 'zh') return 'zh-CN';
  return (lang && String(lang).replace('_', '-')) || 'zh-CN';
}

function clampRate(r) {
  const n = Number(r);
  if (!Number.isFinite(n)) return 1;
  return Math.min(2, Math.max(0.5, n));
}

// Strip markdown so the spoken text is readable (no tables / asterisks / pipes).
function stripForSpeech(s) {
  return String(s)
    .replace(/\|[^\n]*\|/g, ' ')        // table rows
    .replace(/[#*_`>~]/g, ' ')          // common md markers
    .replace(/\s+/g, ' ')
    .trim();
}

// ---- STT ----
// createSTT({ lang, onFinal, onInterim, onState, onError }) -> { start, stop, active }
export function createSTT({ lang = 'zh', onFinal, onInterim, onState, onError } = {}) {
  if (!SR) {
    if (onError) onError(new Error('stt-unsupported'));
    return { start() {}, stop() {}, get active() { return false; } };
  }
  let recognition = null;
  let active = false;

  const stop = () => {
    if (recognition) { try { recognition.stop(); } catch { /* ignore */ } }
    active = false;
    if (onState) onState(false);
  };

  const start = () => {
    if (active) return;
    try { recognition = new SR(); } catch (e) { if (onError) onError(e); return; }
    recognition.lang = langTag(lang);
    recognition.continuous = false;
    recognition.interimResults = true;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => { active = true; if (onState) onState(true); };
    recognition.onend = () => { active = false; if (onState) onState(false); };
    recognition.onerror = (e) => { active = false; if (onState) onState(false); if (onError) onError(e.error || e); };
    recognition.onresult = (ev) => {
      let interim = '';
      let finalText = '';
      for (let i = ev.resultIndex; i < ev.results.length; i++) {
        const res = ev.results[i];
        if (res.isFinal) finalText += res[0].transcript;
        else interim += res[0].transcript;
      }
      if (interim && onInterim) onInterim(interim);
      if (finalText) {
        if (onFinal) onFinal(finalText.trim());
        stop();
      }
    };
    try { recognition.start(); }
    catch (e) { if (onError) onError(e); }
  };

  return { start, stop, get active() { return active; } };
}

// ---- TTS ----
// createTTS() -> { speak(text, opts), cancel(), speaking() }
export function createTTS() {
  let current = null;
  const speak = (text, { voice = null, rate = 1 } = {}) => {
    if (!synth || !text) return;
    cancel();
    const u = new SpeechSynthesisUtterance(stripForSpeech(text));
    const tag = langTag(window.__lang || 'zh');
    // 朗读语言始终以全站语言（window.__lang）为准，确保与整个应用一致
    u.lang = tag;
    if (voice) {
      const v = synth.getVoices().find((x) => x.name === voice);
      const baseLang = (l) => (l || '').replace(/-/g, '').slice(0, 2).toLowerCase();
      // 仅当用户所选音色语言与全站语言一致时才启用，否则跟随全站语言（引擎自动选音色）
      if (v && baseLang(v.lang) === baseLang(tag)) {
        u.voice = v;
        u.lang = v.lang;
      }
    }
    u.rate = clampRate(rate);
    current = u;
    synth.speak(u);
  };
  const cancel = () => {
    if (synth) { try { synth.cancel(); } catch { /* ignore */ } }
    current = null;
  };
  const speaking = () => !!synth && synth.speaking;
  return { speak, cancel, speaking };
}

// Available TTS voices (may be empty until 'voiceschanged' fires).
export function getVoices() {
  if (!synth) return [];
  return synth.getVoices() || [];
}
export function onVoicesChanged(cb) {
  if (!synth) return () => {};
  synth.addEventListener('voiceschanged', cb);
  return () => synth.removeEventListener('voiceschanged', cb);
}

import { handleRoute } from '../../router.js';
import { followState } from './state.js';
const roots = new WeakMap();
let retryPath = null;
export function consumeRetry() {
  const retry = retryPath === location.hash;
  retryPath = null;
  return retry;
}
// Delegate once to the persistent root; update state before rendering.
export function initFollowTeams({ root = document.getElementById('app'), state = followState, refresh = handleRoute } = {}) {
  if (!root) return () => {};
  if (roots.has(root)) return roots.get(root);
  let retrying = false;
  const click = async event => {
    const button = event.target.closest('[data-follow-action]');
    if (!button || !root.contains(button)) return;
    const action = button.dataset.followAction;
    if (action === 'toggle') {
      const code = button.dataset.team;
      state.setFollowed(code, !state.getSnapshot().teamCodes.includes(code));
      await refresh({ preserveScroll: true, focusKey: button.dataset.followFocus });
    } else if (action === 'stage') {
      state.setScheduleFilters({ stage: button.dataset.filter });
      await refresh({ preserveScroll: true, focusKey: button.dataset.followFocus });
    } else if (action === 'retry' && !retrying) {
      retrying = true;
      button.disabled = true;
      retryPath = location.hash;
      try {
        await refresh({ preserveScroll: true, focusKey: button.dataset.followFocus });
      } finally {
        retrying = false;
        button.disabled = false;
        retryPath = null;
      }
    }
  };
  const change = async event => {
    const input = event.target;
    if (input.matches('input[type="checkbox"][data-follow-action="filter"]')) {
      state.setScheduleFilters({ followOnly: input.checked });
      await refresh({ preserveScroll: true, focusKey: input.dataset.followFocus });
    }
  };
  root.addEventListener('change', change);
  root.addEventListener('click', click);
  const dispose = () => { root.removeEventListener('change', change); root.removeEventListener('click', click); roots.delete(root); };
  roots.set(root, dispose);
  return dispose;
}

import { STAGES } from '../../utils.js';

export const stageOrder = Object.freeze(Object.keys(STAGES).sort((a,b) => STAGES[a].order - STAGES[b].order));
export function matchCategory(match) {
  const category = match?.stage === 'knockout' ? match.round : match?.stage;
  return stageOrder.includes(category) ? category : null;
}
export const isFilterStage = stage => stage === 'all' || stageOrder.includes(stage);

export function selectMatches(matches, { teamCodes, followOnly, stage }) {
  const followed = new Set(teamCodes);
  const seen = new Set();
  return matches.filter(m => {
    const teamMatches = !followOnly || (followed.has(m.home.code) || followed.has(m.away.code));
    const stageMatches = stage === 'all' || matchCategory(m) === stage;
    if (!(teamMatches && stageMatches) || seen.has(m.id)) return false;
    seen.add(m.id);
    return true;
  });
}

import { isFilterStage } from './matches.js';
import { browserStorage } from '../../browser-storage.js';

export const FOLLOW_KEY = 'wc2026-followed-teams';
export function createFollowState({ storage = browserStorage } = {}) {
  let initialized = false;
  let allowed = new Set();
  const followed = new Set();
  let restoreIssue = null;
  let saveIssue = null;
  let followOnly = false;
  let stage = 'all';

  const getSnapshot = () => ({ initialized, teamCodes: [...followed].sort(), followOnly, stage, restoreIssue, saveIssue });

  function initialize(teams) {
    if (initialized || !teams || typeof teams !== 'object' || Array.isArray(teams)) return getSnapshot();
    allowed = new Set(Object.keys(teams));
    initialized = true;
    const saved = storage.read(FOLLOW_KEY);
    if (!saved.ok) restoreIssue = 'unavailable';
    else if (saved.value !== null) {
      try {
        const value = JSON.parse(saved.value);
        if (!value || value.version !== 1 || !Array.isArray(value.teamCodes)) throw new Error('invalid record');
        for (const code of value.teamCodes) if (typeof code === 'string' && allowed.has(code)) followed.add(code);
      } catch { restoreIssue = 'corrupt'; }
    }
    return getSnapshot();
  }

  function setFollowed(code, desired) {
    if (!initialized || !allowed.has(code) || typeof desired !== 'boolean') return getSnapshot();
    if (followed.has(code) === desired) return getSnapshot();
    if (desired) followed.add(code); else followed.delete(code);
    const result = storage.write(FOLLOW_KEY, JSON.stringify({ version: 1, teamCodes: [...followed].sort() }));
    if (result.ok) { saveIssue = null; restoreIssue = null; }
    else saveIssue = 'failed';
    return getSnapshot();
  }

  function setScheduleFilters(patch = {}) {
    if (typeof patch.followOnly === 'boolean') followOnly = patch.followOnly;
    if (isFilterStage(patch.stage)) stage = patch.stage;
    return getSnapshot();
  }
  return { getSnapshot, initialize, setFollowed, setScheduleFilters };
}
export const followState = createFollowState();

import { t } from '../../i18n.js';
export function renderFollowNotice(snapshot) {
  const messages = [];
  if (snapshot.restoreIssue) messages.push(t('follow.restore.' + snapshot.restoreIssue));
  if (snapshot.saveIssue) messages.push(t('follow.saveFailed'));
  return messages.length ? '<p class="follow-notice" role="status">' + messages.join(' · ') + '</p>' : '';
}
export function renderDataError(snapshot) {
  return '<div class="follow-empty"><h2>' + t('follow.loadError') + '</h2>' + renderFollowNotice(snapshot) +
    '<button type="button" class="filter-btn" data-follow-action="retry" data-follow-focus="follow-retry">' + t('follow.retry') + '</button></div>';
}

