  if (!els.container || !els.input || !els.results) return;

  try {
    const [teams, matches, playerNames] = await Promise.all([
      getTeams(), getMatches(), getPlayerNames()
    ]);
    data = buildIndex(teams, matches, playerNames);
  } catch (e) {
    console.warn('Search index build failed:', e);
    data = { teams: [], matches: [], players: [] };
  }

  bindEvents();
  updatePlaceholder();
}

// Refresh placeholder + re-render open panel on language switch
export function refreshSearch() {
  if (!els.input) return;
  updatePlaceholder();
  if (els.results.classList.contains('open') && els.input.value.trim()) {
    render(els.input.value);
  }
}

function buildIndex(teams, matches, playerNames) {
  const teamArr = Object.values(teams).map(tm => ({
    code: tm.code,
    name: tm.name,
    group: tm.group,
    confederation: tm.confederation,
    search: [tm.code, tm.name.en, tm.name.zh, tm.confederation]
      .filter(Boolean).join(' ').toLowerCase()
  }));

  const matchArr = matches.map(m => ({
    id: m.id,
    home: m.home,
    away: m.away,
    homeScore: m.homeScore,
    awayScore: m.awayScore,
    stage: m.stage,
    round: m.round,
    search: [m.home.code, m.away.code, m.home.name, m.away.name,
      m.home.nameZh, m.away.nameZh, String(m.id)]
      .filter(Boolean).join(' ').toLowerCase()
  }));

  // Aggregate players from goals + cards across all matches
  const pmap = {};
  matches.forEach(m => {
    const add = (p, team) => {
      if (!p || !p.player) return;
      if (!pmap[p.player]) {
        pmap[p.player] = { name: p.player, zh: playerNames[p.player], team, count: 0 };
      }
      pmap[p.player].count++;
    };
    (m.goals || []).forEach(g => add(g, g.team));
    (m.cards || []).forEach(c => add(c, c.team));
  });
  const playerArr = Object.values(pmap).map(p => ({
    name: p.name,
    zh: p.zh,
    team: p.team,
    count: p.count,
    search: [p.name, p.zh, p.team].filter(Boolean).join(' ').toLowerCase()
  }));

  return { teams: teamArr, matches: matchArr, players: playerArr };
}

function query(q) {
  q = q.trim().toLowerCase();
  if (!q) return null;
  return {
    teams: data.teams.filter(t => t.search.includes(q)).slice(0, 6),
    matches: data.matches.filter(m => m.search.includes(q)).slice(0, 6),
    players: data.players.filter(p => p.search.includes(q)).slice(0, 6),
  };
}

function render(q) {
  const res = query(q);
  if (!res) { close(); return; }

  const has = res.teams.length || res.matches.length || res.players.length;
  if (!has) {
    els.results.innerHTML = `<div class="search-empty">${t('search.noResults')}</div>`;
    open(); flat = []; active = -1;
    return;
  }

  const lang = window.__lang || 'zh';
  const items = [];

  if (res.teams.length) {
    items.push({ label: t('search.teams') });
    res.teams.forEach(tm => {
      const grp = tm.group
        ? (lang === 'zh' ? `第${tm.group}组` : `Group ${tm.group}`)
        : '';
      items.push({
        href: `#/team/${tm.code}`,
        html: `${flagSVG(tm.code, 'sm')}` +
          `<span class="search-name">${L(tm.name)}</span>` +
          `<span class="search-sub">${tm.code}${grp ? ' · ' + grp : ''}</span>`
      });
    });
  }

  if (res.matches.length) {
    items.push({ label: t('search.matches') });
    res.matches.forEach(m => {
      const homeName = (m.home.nameZh && lang === 'zh') ? m.home.nameZh : m.home.name;
      const awayName = (m.away.nameZh && lang === 'zh') ? m.away.nameZh : m.away.name;
      const score = (m.homeScore != null && m.awayScore != null)
        ? `${m.homeScore}-${m.awayScore}`
        : (lang === 'zh' ? '未赛' : '–');
      items.push({
        href: `#/match/${m.id}`,
        html: `${flagSVG(m.home.code, 'sm')}${flagSVG(m.away.code, 'sm')}` +
          `<span class="search-name">${homeName} <b>${score}</b> ${awayName}</span>` +
          `<span class="search-sub">#${m.id} · ${stageLabel(m)}</span>`
      });
    });
  }

  if (res.players.length) {
    items.push({ label: t('search.players') });
    res.players.forEach(p => {
      const pname = (p.zh && lang === 'zh') ? p.zh : p.name;
      const sub = lang === 'zh' ? `${p.team} · 出场 ${p.count} 次` : `${p.team} · ${p.count} apps`;
      items.push({
        href: `#/team/${p.team}`,
        html: `${flagSVG(p.team, 'sm')}` +
          `<span class="search-name">${pname}</span>` +
          `<span class="search-sub">${sub}</span>`
      });
    });
  }

  let html = '';
  flat = [];
  items.forEach(it => {
    if (it.label !== undefined) {
      html += `<div class="search-group">${it.label}</div>`;
    } else {
      const idx = flat.length;
      html += `<a class="search-item" href="${it.href}" data-idx="${idx}">${it.html}</a>`;
      flat.push(it.href);
    }
  });

  els.results.innerHTML = html;
  active = -1;
  open();
}

function open() { els.results.classList.add('open'); }
function close() { els.results.classList.remove('open'); active = -1; }

function onKey(e) {
  if (e.key === 'Escape') { close(); els.input.blur(); return; }
  if (!flat.length) return;
  if (e.key === 'ArrowDown') { e.preventDefault(); move(1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); }
  else if (e.key === 'Enter') {
    if (active >= 0 && flat[active]) {
      e.preventDefault();
      location.hash = flat[active];
      close();
    }
  }
}

function move(dir) {
  const nodes = els.results.querySelectorAll('.search-item');
  if (!nodes.length) return;
  if (active >= 0 && nodes[active]) nodes[active].classList.remove('active');
  active = (active + dir + nodes.length) % nodes.length;
  nodes[active].classList.add('active');
  nodes[active].scrollIntoView({ block: 'nearest' });
}

function updatePlaceholder() {
  els.input.placeholder = t('search.placeholder');
}

function bindEvents() {
  els.input.addEventListener('input', () => render(els.input.value));
  els.input.addEventListener('focus', () => {
    if (els.input.value.trim()) render(els.input.value);
  });
  els.input.addEventListener('keydown', onKey);

  // Close when clicking outside the search container
  document.addEventListener('click', (e) => {
    if (!els.container.contains(e.target)) close();
  });

  // Close after navigating
  window.addEventListener('hashchange', () => close());

  // Global "/" shortcut to focus the search box
  document.addEventListener('keydown', (e) => {
    const tag = (document.activeElement && document.activeElement.tagName) || '';
    const typing = tag === 'INPUT' || tag === 'TEXTAREA';
    if (e.key === '/' && !typing && document.activeElement !== els.input) {
      e.preventDefault();
      els.input.focus();
    }
  });
}

import { t } from '../../i18n.js';
import { groupFilterState, isGroupVisible } from './state.js';
import { getCounts } from './count.js';

const roots = new WeakMap();
export function initTeamGroupFilter({ root = document.getElementById('app'), state = groupFilterState } = {}) {
  if (!root) return () => {};
  if (roots.has(root)) return roots.get(root);
  const update = page => {
    const { selectedGroups } = state.getSnapshot();
    for (const input of page.querySelectorAll('input[data-team-group]')) input.checked = selectedGroups.includes(input.dataset.teamGroup);
    for (const section of page.querySelectorAll('.group-card[data-team-group]')) section.hidden = !isGroupVisible(section.dataset.teamGroup, selectedGroups);
    page.querySelector('[data-team-group-summary]').textContent = t('teams.filter.count', getCounts(selectedGroups));
  };
  const change = event => {
    const input = event.target;
    const page = input.closest?.('.teams-page');
    if (!page || !root.contains(page) || !input.matches('input[type="checkbox"][data-team-group-action="select"]')) return;
    state.setSelected(input.dataset.teamGroup, input.checked);
    update(page);
  };
  const click = event => {
    const button = event.target.closest?.('button[data-team-group-action="all"]');
    const page = button?.closest('.teams-page');
    if (!page || !root.contains(page)) return;
    state.clear();
    update(page);
  };
  root.addEventListener('change', change);
  root.addEventListener('click', click);
  const dispose = () => {
    root.removeEventListener('change', change);
    root.removeEventListener('click', click);
    roots.delete(root);
  };
  roots.set(root, dispose);
  return dispose;
}

import { isGroupVisible } from './state.js';

export function countTeamGroups(groups, selectedGroups) {
  let visible = 0;
  let total = 0;
  for (const group of groups) {
    total += group.teams.length;
    if (isGroupVisible(group.key, selectedGroups)) visible += group.teams.length;
  }
  return { visible, total };
}

let currentGroups = [];
export function setGroups(groups) { currentGroups = groups; }
export function getCounts(selectedGroups) { return countTeamGroups(currentGroups, selectedGroups); }

export function buildTeamGroups(teams) {
  const groups = new Map();
  for (const team of Object.values(teams)) {
    const key = typeof team.group === 'string' ? team.group.trim() : '';
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(team);
  }
  return [...groups.keys()].filter(Boolean).sort().concat(groups.has('') ? [''] : [])
    .map(key => ({ key, teams: groups.get(key) }));
}
export function isGroupVisible(group, selected) {
  return selected.length === 0 || selected.includes(group);
}
export function createGroupFilterState() {
  let available = new Set();
  const selected = new Set();
  return {
    syncGroups(groups) {
      available = new Set(groups.filter(Boolean));
      for (const group of selected) if (!available.has(group)) selected.delete(group);
    },
    setSelected(group, checked) {
      if (!available.has(group)) return;
      if (checked) selected.add(group);
      else selected.delete(group);
    },
    clear() { selected.clear(); },
    getSnapshot() { return { availableGroups: [...available].sort(), selectedGroups: [...selected].sort() }; },
  };
}
export const groupFilterState = createGroupFilterState();

import { browserStorage } from './browser-storage.js';
// ===== i18n Engine =====

let dict = {};
let currentLang = 'zh';
let intendedLang = 'zh';
let requestId = 0;

function detectLang() {
  const saved = browserStorage.read('wc2026-lang').value;
  if (saved === 'zh' || saved === 'en') return saved;
  const nav = navigator.language || 'zh';
  return nav.toLowerCase().startsWith('zh') ? 'zh' : 'en';
}

export async function initI18n() {
  await requestLanguage(detectLang(), false);
}

async function loadDict(lang) {
  try {
    const resp = await fetch(`i18n/${lang}.json`);
    if (!resp.ok) throw new Error('Dictionary request failed');
    return await resp.json();
  } catch (e) {
    console.warn('Failed to load i18n dict:', e);
    return {};
  }
}

export function t(key, vars) {
  let s = dict[key];
  if (s === undefined) s = key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      s = s.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
    }
  }
  return s;
}

async function requestLanguage(lang, notify) {
  if (lang !== 'zh' && lang !== 'en') return;
  intendedLang = lang;
  const id = ++requestId;
  const nextDict = await loadDict(lang);
  if (id !== requestId) return;
  dict = nextDict;
  currentLang = lang;
  browserStorage.write('wc2026-lang', lang);
  document.documentElement.lang = lang;
  window.__lang = lang;
  if (notify) document.dispatchEvent(new CustomEvent('langchange', { detail: { lang } }));
}

export async function setLang(lang) {
  await requestLanguage(lang, true);
}

export function getLang() { return currentLang; }

export function toggleLang() {
  return setLang(intendedLang === 'zh' ? 'en' : 'zh');
}

// ===== Hash Router =====

const routes = [];
let navigationId = 0;

export function addRoute(pattern, handler) {
  routes.push({ pattern, handler });
}

function getHash() {
  return location.hash.slice(1) || '/';
}

function matchRoute(path) {
  for (const route of routes) {
    const match = path.match(route.pattern);
    if (match) {
      return { handler: route.handler, params: match.slice(1) };
    }
  }
  return null;
}

export async function handleRoute(options = {}) {
  const requestId = ++navigationId;
  const path = getHash();
  const matched = matchRoute(path);

  const app = document.getElementById('app');
  if (!app) return { committed: false, path };
  let currentView;

  // Show loading
  if (!options.preserveScroll) {
    app.innerHTML = '<div class="loading"><div class="loading-spinner"></div><p id="loadingText">Loading...</p></div>';
  }

  // Update loading text
  const loadingText = document.getElementById('loadingText');
  if (loadingText) {
    const lang = window.__lang || 'zh';
    loadingText.textContent = lang === 'zh' ? '加载中...' : 'Loading...';
  }

  try {
    if (matched) {
      currentView = await matched.handler(...matched.params);
    } else {
      // 404
      const { default: notFound } = await import('./views/not-found.js');
      currentView = notFound();
    }
  } catch (e) {
    console.error('Route error:', e);
    currentView = `<div class="loading"><p>Error: ${e.message}</p></div>`;
  }

  // A slower, older route must never replace the currently requested page.
  if (requestId !== navigationId) return { committed: false, path };

  app.innerHTML = currentView;
  app.classList.add('app-container');

  // Re-trigger animation
  app.style.animation = 'none';
  void app.offsetWidth;
  app.style.animation = '';

  // Update nav active state
  updateNavActive(path);

  // Add mouse tracking to match cards for radial glow effect
  document.querySelectorAll('.match-card').forEach(card => {
    card.addEventListener('mousemove', (e) => {
      const rect = card.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      const y = ((e.clientY - rect.top) / rect.height) * 100;
      card.style.setProperty('--mx', x + '%');
      card.style.setProperty('--my', y + '%');
    });
  });

  // Scroll to top
  if (!options.preserveScroll) window.scrollTo(0, 0);
  const focusKeys = ['follow-team', 'follow-only', 'follow-retry', 'follow-stage-all', 'follow-stage-group',
    'follow-stage-round_of_32', 'follow-stage-round_of_16', 'follow-stage-quarterfinal',
    'follow-stage-semifinal', 'follow-stage-third_place', 'follow-stage-final'];
  if (focusKeys.includes(options.focusKey)) {
    const target = [...app.querySelectorAll('[data-follow-focus]')]
      .find(el => el.dataset.followFocus === options.focusKey);
    target?.focus({ preventScroll: true });
  }
  return { committed: true, path };
}

function updateNavActive(path) {
  document.querySelectorAll('.nav-link').forEach(link => {
    const href = link.getAttribute('href').slice(1);
    const isActive = path === href || (href !== '/' && path.startsWith(href));
    link.classList.toggle('active', isActive || (path === '/' && href === '/'));
  });
}

export function navigate(path) {
  location.hash = path;
}

export function initRouter() {
  window.addEventListener('hashchange', handleRoute);
  document.addEventListener('click', (event) => {
    const routeTarget = event.target.closest('[data-route]');
    if (!routeTarget) return;
    const path = routeTarget.dataset.route;
    if (!path) return;
    event.preventDefault();
    navigate(path);
  });
  document.addEventListener('error', (event) => {
    const image = event.target;
    if (!image.matches?.('img.flag')) return;
    image.style.display = 'none';
    const fallback = image.nextElementSibling;
    if (fallback?.classList.contains('flag-fallback')) fallback.style.display = 'flex';
  }, true);
  document.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    const routeTarget = event.target.closest?.('[data-route][role="link"]');
    if (!routeTarget) return;
    event.preventDefault();
    navigate(routeTarget.dataset.route);
  });
  handleRoute();
}

/** Shared, environment-neutral dataset boundary for browser BYOK and Functions. */
export const ROUND_ALIASES = Object.freeze({
  r32: 'round_of_32', r16: 'round_of_16', qf: 'quarterfinal', sf: 'semifinal',
  third: 'third_place', third_place: 'third_place', final: 'final',
  quarterfinals: 'quarterfinal', semifinals: 'semifinal',
});

export function normalizeRound(input) {
  if (!input) return null;
  const key = String(input).toLowerCase().trim();
  if (ROUND_ALIASES[key]) return ROUND_ALIASES[key];
  if (key.includes('round_of_32')) return 'round_of_32';
  if (key.includes('round_of_16')) return 'round_of_16';
  if (key.includes('quarter')) return 'quarterfinal';
  if (key.includes('semi')) return 'semifinal';
  return null;
}

export function normalizeTournamentDataset(raw = {}) {
