// ===== Schedule View =====
import { t } from '../i18n.js';
import { getTournamentSnapshot } from '../store.js';
import { L, formatDate, flagSVG, stageLabel, translateStadium } from '../utils.js';
import { followState } from '../features/follow-teams/state.js';
import { matchCategory, stageOrder, selectMatches } from '../features/follow-teams/matches.js';
import { consumeRetry } from '../features/follow-teams/controller.js';
import { renderFollowNotice, renderDataError } from '../features/follow-teams/view.js';

export default async function scheduleView() {
  const result = await getTournamentSnapshot({ retry: consumeRetry() });
  if (result.status !== 'ready') return renderDataError(followState.getSnapshot());
  followState.initialize(result.teams);
  const snapshot = followState.getSnapshot();
  const matches = selectMatches(result.matches, snapshot);
  const teams = result.teams;
  const present = new Set(result.matches.map(matchCategory));
  const tabs = stageOrder.filter(c => present.has(c));
  let html = '<div class="schedule-page"><h1 class="page-title">' + t('nav.schedule') + '</h1>';
  html += '<p class="page-subtitle" data-follow-count role="status">' + t('follow.count', { count: matches.length }) + '</p>';
  html += '<div class="follow-controls"><label class="follow-switch"><input type="checkbox" data-follow-action="filter" data-follow-focus="follow-only" ' + (snapshot.followOnly ? 'checked' : '') + '> ' + t('follow.only') + '</label></div>';
  html += renderFollowNotice(snapshot);
  html += '<p class="follow-demo">' + t('follow.demo') + '</p>';
  html += '<div class="filter-tabs" id="scheduleFilter">';
  for (const cat of ['all', ...tabs]) {
    const active = snapshot.stage === cat;
    html += '<button type="button" class="filter-tab ' + (active ? 'active' : '') + '" aria-pressed="' + active + '" data-follow-action="stage" data-filter="' + cat + '" data-follow-focus="follow-stage-' + cat + '">' + (cat === 'all' ? t('schedule.all') : stageLabel(cat)) + '</button>';
  }
  html += '</div>';
  if (!matches.length) {
    html += '<div class="follow-empty"><p>' + t(snapshot.followOnly && !snapshot.teamCodes.length ? 'follow.noTeams' : 'follow.noMatches') + '</p><a href="#/teams" class="back-link">' + t('follow.chooseTeams') + '</a></div>';
  }
  for (const cat of tabs) {
    const catMatches = matches.filter(m => matchCategory(m) === cat);
    if (cat === 'group') {
      const groups = [...new Set(catMatches.map(m => m.group || '?'))].sort();
      for (const group of groups) {
        html += '<div class="match-section" data-stage="group" data-group="' + group + '"><h2 class="section-title">' + t('common.group') + ' ' + group + '</h2><div class="match-grid">';
        for (const m of catMatches.filter(m => (m.group || '?') === group)) html += renderMatchCard(m, teams);
        html += '</div></div>';
      }
    } else if (catMatches.length) {
      html += '<div class="match-section" data-stage="' + cat + '"><h2 class="section-title">' + stageLabel(cat) + '</h2><div class="match-grid">';
      for (const m of catMatches) html += renderMatchCard(m, teams);
      html += '</div></div>';
    }
  }
  return html + '</div>';
}

function renderMatchCard(m, teams) {
  const ht = teams[m.home.code] || { name: m.home.code, code: m.home.code };
  const at = teams[m.away.code] || { name: m.away.code, code: m.away.code };
  const penScore = m.penaltyShootout
    ? `<div class="match-pen-score"><span class="pen-label">${t('match.penalties')}</span> <span class="pen-val">${m.penaltyShootout.home}-${m.penaltyShootout.away}</span></div>`
    : '';
  const score = `<span class="score-num">${m.homeScore}</span><span class="sep">-</span><span class="score-num">${m.awayScore}</span>`;
  const badges = [];
  if (m.extraTime) badges.push(`<span class="badge badge-aet">${t('match.extraTime')}</span>`);
  if (m.penaltyShootout) badges.push(`<span class="badge badge-pen">${t('match.penalties')}</span>`);

  return `
    <div class="match-card" data-route="/match/${m.id}" role="link" tabindex="0">
      <div class="match-card-header">
        <span class="match-card-date">${formatDate(m.date)} ${m.time || ''}</span>
        <span class="match-card-stage">${stageLabel(m)}</span>
      </div>
      <div class="match-card-body">
        <div class="match-team home">
          <span class="match-team-name">${L(ht.name)}</span>
          ${flagSVG(ht.code || m.home.code)}
        </div>
        <div class="match-score">${score}${penScore}</div>
        <div class="match-team away">
          ${flagSVG(at.code || m.away.code)}
          <span class="match-team-name">${L(at.name)}</span>
        </div>
      </div>
      ${badges.length ? `<div style="margin-top:8px;text-align:center">${badges.join('')}</div>` : ''}
      <div class="match-card-footer">
        <span class="venue">${translateStadium(m.stadium) || ''}</span>
        <span>${m.id}</span>
      </div>
    </div>`;
}

// ===== Team Detail View =====
import { t } from '../i18n.js';
import { getTournamentSnapshot, getTeamTopScorers } from '../store.js';
import { followState } from '../features/follow-teams/state.js';
import { consumeRetry } from '../features/follow-teams/controller.js';
import { renderFollowNotice, renderDataError } from '../features/follow-teams/view.js';
import { L, formatDate, flagSVG, stageLabel, icon, translatePlayer, translateStadium } from '../utils.js';

export default async function teamDetailView(teamCode) {
  const result = await getTournamentSnapshot({ retry: consumeRetry() });
  if (result.status !== 'ready') return renderDataError(followState.getSnapshot());
  followState.initialize(result.teams);
  const team = /^[A-Z]{3}$/.test(teamCode) ? result.teams[teamCode] : null;

  if (!team) {
    return `<div class="loading"><p>${t('follow.teamNotFound')}</p><a href="#/teams" class="back-link">${t('common.back')}</a></div>`;
  }

  const allTeams = result.teams;
  const matches = result.matches.filter(m => m.home.code === team.code || m.away.code === team.code);
  const topScorers = await getTeamTopScorers(team.code);
  const snapshot = followState.getSnapshot();
  const followed = snapshot.teamCodes.includes(team.code);
  const lang = window.__lang || 'zh';

  // Sort matches by date
  matches.sort((a, b) => a.date.localeCompare(b.date));

  const stats = team.stats || {};

  let html = `<div class="team-detail-page">`;
  html += `<a href="#/teams" class="back-link">${icon('back')} ${t('common.back')}</a>`;

  // Header
  html += `<div class="team-header">
    ${flagSVG(team.code, 'lg')}
    <div class="team-header-info">
      <h2>${L(team.name)}</h2>
      <p>${team.confederation || ''} · ${t('common.group')} ${team.group || ''}${team.ranking != null ? ' · ' + (lang === 'zh' ? '排名' : 'Ranking') + ' #' + team.ranking : ''}</p>
    </div>
  </div>`;

  html += '<div class="follow-controls"><button type="button" class="filter-btn" data-follow-action="toggle" data-team="' + team.code + '" data-follow-focus="follow-team" aria-pressed="' + followed + '">' + t(followed ? 'follow.unfollow' : 'follow.follow') + '</button></div>';
  html += renderFollowNotice(snapshot);
  html += '<p class="follow-demo">' + t('follow.demo') + '</p>';

  // Stats table
  html += `<h2 class="section-title">${t('team.stats')}</h2>`;
  const gdVal = stats.goalDifference ?? 0;
  html += `<div class="table-wrap"><table class="standings-table"><thead><tr>
    <th>${t('standings.played')}</th>
    <th>${t('standings.win')}</th>
    <th>${t('standings.draw')}</th>
    <th>${t('standings.loss')}</th>
    <th>${t('standings.gf')}</th>
    <th>${t('standings.ga')}</th>
    <th>${t('standings.gd')}</th>
    <th>${t('standings.pts')}</th>
  </tr></thead><tbody><tr>
    <td>${stats.played ?? 0}</td>
    <td style="color:var(--win)">${stats.won ?? 0}</td>
    <td style="color:var(--draw)">${stats.drawn ?? 0}</td>
    <td style="color:var(--loss)">${stats.lost ?? 0}</td>
    <td>${stats.goalsFor ?? 0}</td>
    <td>${stats.goalsAgainst ?? 0}</td>
    <td>${gdVal > 0 ? '+' : ''}${gdVal}</td>
    <td class="pts">${stats.points ?? 0}</td>
  </tr></tbody></table></div>`;

  // Top scorers
  if (topScorers.length) {
    html += `<h2 class="section-title">${t('team.topScorers')}</h2>`;
    html += `<div class="top-scorers">`;
    topScorers.forEach((s, i) => {
      html += `<div class="scorer-row">
        <span><strong>${i + 1}.</strong> ${translatePlayer(s.player)} ${s.penalties > 0 ? `<span style="color:var(--text-muted);font-size:0.78rem">(${s.penalties} ${t('team.pen')})</span>` : ''}</span>
        <span class="pts" style="color:var(--accent);font-weight:800">${s.goals}</span>
      </div>`;
    });
    html += `</div>`;
  }

  // Matches
  html += `<h2 class="section-title">${t('team.matches')}</h2>`;
  html += `<div class="match-grid">`;
  for (const m of matches) {
    const isHome = m.home.code === team.code;
    const oppCode = isHome ? m.away.code : m.home.code;
    const oppData = isHome ? m.away : m.home;
    // Prefer the {en,zh} name from teams.json; fall back to the match's name/nameZh.
    const opp = allTeams[oppCode] || { name: { en: oppData.name, zh: oppData.nameZh || oppData.name }, code: oppCode };
    const myScore = isHome ? m.homeScore : m.awayScore;
    const oppScore = isHome ? m.awayScore : m.homeScore;
    // Score display: left score = left team, right score = right team
    const leftScore = isHome ? myScore : oppScore;
    const rightScore = isHome ? oppScore : myScore;
    const score = leftScore != null && rightScore != null
      ? `<span class="score-num">${leftScore}</span><span class="sep">-</span><span class="score-num">${rightScore}</span>`
      : `<span class="vs">${t('common.vs')}</span>`;
    const resultColor = (myScore != null && oppScore != null)
      ? (myScore > oppScore ? 'var(--win)' : myScore < oppScore ? 'var(--loss)' : 'var(--draw)')
      : '';

    html += `<div class="match-card" data-route="/match/${m.id}" role="link" tabindex="0">
      <div class="match-card-header">
        <span class="match-card-date">${formatDate(m.date)}</span>
        <span class="match-card-stage">${stageLabel(m)}</span>
      </div>
      <div class="match-card-body">
        <div class="match-team home">
          <span class="match-team-name">${isHome ? L(team.name) : L(opp.name)}</span>
          ${flagSVG(isHome ? team.code : oppCode)}
        </div>
        <div class="match-score" style="${resultColor ? `color:${resultColor}` : ''}">${score}</div>
        <div class="match-team away">
          ${flagSVG(isHome ? oppCode : team.code)}
          <span class="match-team-name">${isHome ? L(opp.name) : L(team.name)}</span>
        </div>
      </div>
      <div class="match-card-footer">
        <span class="venue">${translateStadium(m.stadium) || ''}</span>
        <span>${isHome ? t('team.home') : t('team.away')}</span>
      </div>
    </div>`;
  }
  html += `</div>`;

  html += `</div>`;
  return html;
}

// ===== Teams List View =====
import { t } from '../i18n.js';
import { getTeams } from '../store.js';
import { L, flagSVG } from '../utils.js';
import { buildTeamGroups, groupFilterState, isGroupVisible } from '../features/team-group-filter/state.js';
import { setGroups, getCounts } from '../features/team-group-filter/count.js';

export default async function teamsView() {
  const teams = await getTeams();
  const groups = buildTeamGroups(teams);
  setGroups(groups);
  groupFilterState.syncGroups(groups.map(group => group.key));
  const { availableGroups, selectedGroups } = groupFilterState.getSnapshot();

  let html = `<div class="teams-page">`;
  html += `<h1 class="page-title">${t('nav.teams')}</h1>`;
  html += `<p class="page-subtitle">${t('teams.subtitle')}</p>`;
  if (!groups.length) return html + `<p role="status">${t('teams.filter.unavailable')}</p></div>`;

  html += `<fieldset class="team-group-filter"><legend>${t('teams.filter.legend')}</legend><div class="team-group-options">`;
  for (const group of availableGroups) {
    html += `<label class="team-group-option"><input type="checkbox" data-team-group-action="select" data-team-group="${group}"${selectedGroups.includes(group) ? ' checked' : ''}> ${t('common.group')} ${group}</label>`;
  }
  html += `<button type="button" class="filter-btn" data-team-group-action="all">${t('teams.filter.all')}</button></div></fieldset>`;
  html += `<p class="team-group-summary" data-team-group-summary role="status">${t('teams.filter.count', getCounts(selectedGroups))}</p>`;

  html += `<div class="group-grid">`;
  for (const group of groups) {
    html += `<div class="group-card" data-team-group="${group.key}"${isGroupVisible(group.key, selectedGroups) ? '' : ' hidden'}>`;
    html += `<h3>${group.key ? t('common.group') + ' ' + group.key : t('teams.filter.unknownGroup')}</h3>`;
    html += `<div style="display:flex;flex-direction:column;gap:8px">`;
    for (const team of group.teams) {
      const conf = team.confederation || '';
      const rank = team.ranking != null ? `#${team.ranking}` : '';
      const sub = [conf, rank].filter(Boolean).join(' · ');
      html += `<div class="team-search-result" data-route="/team/${team.code}" role="link" tabindex="0" style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;background:var(--bg-elevated);transition:all 0.25s">
        ${flagSVG(team.code, 'sm')}
        <span style="font-weight:600;font-size:0.88rem">${L(team.name)}</span>
        ${sub ? `<span style="margin-left:auto;font-size:0.72rem;color:var(--text-muted)">${sub}</span>` : ''}
      </div>`;
    }
    html += `</div></div>`;
  }
  html += `</div></div>`;
  return html;
}
